import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { catchError, map, Observable, throwError } from 'rxjs';
import { RouteAiQueryParams, RouteAiResponse, SaveRouteResponse } from '../interfaces/route-ai.interface';
import { ResponsePaginator } from '../../../shared/interfaces/paginator.interface';

/** Servicio para las rutas generadas por IA del usuario autenticado. */
@Injectable({
  providedIn: 'root',
})
export class RouteService {

  private _http = inject(HttpClient)

  /** GET routes generated by AI and requested by the authenticated user. */
  getRoutesAiUser(params: RouteAiQueryParams = {}): Observable<ResponsePaginator<RouteAiResponse>> {
    let query = new HttpParams()
      .set('page', params.page ?? 1)
      .set('ordering', params.ordering ?? '-id')

    if (params.search) {
      query = query.set('search', params.search)
    }
    if (params.saved !== undefined) {
      query = query.set('saved', params.saved)
    }

    return this._http.get<ResponsePaginator<RouteAiResponse>>('ai-route', { params: query })
  }

  /** Delete a route generated by AI by id. */
  deleteRoute(id: number): Observable<void> {
    return this._http.delete<void>(`ai-route/${id}/`)
  }

  /** Mark a route generated by AI as saved or unsaved. */
  saveRoute(id: number, saved: boolean): Observable<RouteAiResponse> {
    const body = { saved }
    return this._http.patch<SaveRouteResponse>(`ai-route/${id}/saved/`, body).pipe(
      catchError((error: HttpErrorResponse) =>
        error.status === 404
          ? this._http.patch<SaveRouteResponse>(`ai-route/${id}/`, body)
          : throwError(() => error),
      ),
      map((response) => ('route' in response ? response.route : response)),
    )
  }
}
